// WireAssignment is the assignment of values to the same wire across many instances of the
// circuit: WireAssignment[wireI][instanceI] is the value of wire wireI at instance instanceI. The
// values are mamabear.Element elements; the claims that Prove and Verify return are over extensions.E3.
type WireAssignment []basePolynomial.MultiLin

// Proof is a GKR proof: one sumcheck proof per level of the proving schedule, followed by the
// output level's entry.
type Proof []sumcheckProof

// EvaluationClaim is an assertion that a wire's multilinear extension evaluates to Evaluation at
// EvaluationPoint.
type EvaluationClaim = gkr.EvaluationClaim[extensions.E3]

// Claims are the evaluation claims on circuit inputs and outputs that Prove and Verify return, by
// wire. The consumption order within a wire's slice is up to the caller.
type Claims map[int][]EvaluationClaim

// Check asserts that every claim in c holds against assignment.
func (c Claims) Check(assignment WireAssignment) error {
	var scratch polynomial.MultiLinE3
	for wI, wireClaims := range c {
		for _, claim := range wireClaims {
			eval := scratch.EvaluateBase(assignment[wI], claim.EvaluationPoint)
			if !eval.Equal(&claim.Evaluation) {
				return fmt.Errorf("wire %d: claimed evaluation %v, computed %v", wI, &claim.Evaluation, &eval)
			}
		}
	}
	return nil
}

